    @EventHandler( payloadType=CreateTimesheetEvent.class )
    public void handle( CreateTimesheetEvent event) {
	    LOGGER.info("handling CreateTimesheetEvent - " + event );
	    Timesheet entity = new Timesheet();
            entity.setTimesheetId( event.getTimesheetId() );
            entity.setPeriodStart( event.getPeriodStart() );
            entity.setPeriodEnd( event.getPeriodEnd() );
            entity.setSubmissionDate( event.getSubmissionDate() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllTimesheet( entity );
    }

