    /**
     * Method to retrieve the Timesheet via an TimesheetPrimaryKey.
     * @param 	id Long
     * @return 	Timesheet
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Timesheet handle( FindTimesheetQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getTimesheetId() );
    }
    
    /**
     * Method to retrieve a collection of all Timesheets
     *
     * @param	query	FindAllTimesheetQuery 
     * @return 	List<Timesheet> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Timesheet> handle( FindAllTimesheetQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindTimesheet,
 * but only if the id matches
 *
 * @param		entity	Timesheet
 */
	protected void emitFindTimesheet( Timesheet entity ) {
		LOGGER.info("handling emitFindTimesheet" );
		
	    queryUpdateEmitter.emit(FindTimesheetQuery.class,
	                            query -> query.getFilter().getTimesheetId().equals(entity.getTimesheetId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTimesheet
	 * 
	 * @param		entity	Timesheet
	 */
	protected void emitFindAllTimesheet( Timesheet entity ) {
		LOGGER.info("handling emitFindAllTimesheet" );
		
	    queryUpdateEmitter.emit(FindAllTimesheetQuery.class,
	                            query -> true,
	                            entity);
	}

